      "## Հագուկապը",
      "Dress code-ը՝ Versailles masquerade, glamour, drama. ոգեշնչման աղբյուրը XVIII դարի արքունական շքեղությունն է, Վերսալի դիմակահանդեսները և բարձր նորաձևության համարձակ երեկոյան զգեստները։ Դիմակը պարտադիր է։",
