      "Երգչախմբի գեղարվեստական ղեկավարն ու խմբավարը Քրիստինա Ոսկանյանն է, մենակատարներն են Նելլի Քալաշյանը, Ժաննա Դավթյանը, Գուրգեն Պողոսյանը և Ջեննի Նազարյանը։",
