      "Հոկտեմբերի 20-ին «Հովեր» պետական կամերային երգչախումբը և Վահագն Հայրապետյան տրիոն Կոմիտասի անվան կամերային երաժշտության տանը ներկայացնում են «Հայկական ժողովրդական երգերի մշակումներ» ծրագիրը՝ Ապարանի և Համշենի երգեր՝ ջազային մշակումներով։",
      "## Ծրագիրը",
      "Ապարանի երգերից՝ «Մեր հայաթը դիփ քյալամ ու բողկ ա», «Յար, մտքիդ մեռնիմ», «Գնացիր, մնացիր», «Հազարներից քեզ եմ սիրել» և «Սինե, Սինե, Սինամե»՝ Վահագն Հայրապետյանի մշակմամբ։ Համշենի «Սիրուն աղճիկ» և «Էլլա, էլլա» երգերը մշակել է Աննա Ազիզյանը, «Առնեմ էլնեմ Ալագյազ»-ը՝ Վահագն Բաբլոյանը, «Երկինքն ամպէ, հովն անուշ»-ը՝ Էդգար Հովհաննիսյանը։",
