      "Դատավոր՝ Հրաչյա Հարությունյան, Պատրիկ Դևեճյան՝ Արթուր Ութմազյան, Պիեր Դյուվալ՝ Արմեն Բարսեղյան։ Չորս մեղադրյալները՝ Վազգեն Սիսլյան՝ Գրիգոր Խաչատրյան, Արամ Բասմաջյան՝ Արմեն Մեսրոբյան, Գևորգ Գյուզելյան՝ Լևոն Հախվերդյան, Հակոբ Ջուլֆայան՝ Նիկոլայ Ավետիսյան։ Իվ Տերնոնին խաղում են Նարեկ Քթոյանը կամ Վլադիմիր Մսրյանը։",
      "## Երբ և որքան",
      "Նոյեմբերի 7-ին և 27-ին, ժամը 19:30-ին, Իսահակյան 28 հասցեում։ Տոմսերը 2500-ից 7000 դրամ են։ Նույն բեմում նոյեմբերի 4-ին <a href=\"/events/hamlet-ghaplanyan-theatre-2026/\" title=\"«Համլետ»՝ Երևանի Ղափլանյանի թատրոնում\">«Համլետն»</a> է։",
