      "Նոյեմբերի 13-ին Mystery Ensemble-ը Կամերային երաժշտության տանը նվագում է ճապոնացի կոմպոզիտոր Ձյո Հիսաիսիի երաժշտությունը՝ գրված Հայաո Միյաձակիի անիմեների համար։ Կազմակերպիչը Red Events-ն է, որը նույն դահլիճ հոկտեմբերին բերում է <a href=\"/am/events/tim-burton-mystery-ensemble-yerevan-2026/\" title=\"Թիմ Բարթոնի ֆիլմերի երաժշտությունը Երևանում\">Թիմ Բարթոնի երեկոն</a>, իսկ դեկտեմբերին՝ <a href=\"/am/events/winter-tales-mystery-ensemble-komitas-house-2026/\" title=\"«Ձմեռային հեքիաթներ» Երևանում\">«Ձմեռային հեքիաթները»</a>։",
      "## Ծրագիրը",
      "Հնչելու են «Հաուլի շարժվող ամրոցը», «Նաուսիկան Քամիների հովտից», «Ոգիների տարած»-ը և «Իմ հարևան Տոտորոն» ֆիլմերի սաունդթրեքները։ Հիսաիսին Միյաձակիի ֆիլմերի երաժշտությունը գրում է 1984-ի «Նաուսիկայից» սկսած և, կազմակերպչի խոսքով, չորս անգամ արժանացել է Ճապոնական կինոակադեմիայի մրցանակին լավագույն երաժշտության համար։ Mystery Ensemble-ը լարային գործիքների, դաշնամուրի և հարվածայինների կազմ է, որը ֆիլմերի երաժշտությունը նվագում է սեփական գործիքավորմամբ։",
      "## Երբ և որքան",
      "Նոյեմբերի 13-ին, ուրբաթ, ժամը 19:00-ին, Իսահակյան 1 հասցեում։ Տոմսերը 9300 և 11500 դրամ են։ Հոկտեմբերի 21-ի դրությամբ տոմսարկղը նշում էր, որ մնացել է ընդամենը 19 տեղ։ Կազմակերպիչը համերգը ներկայացնում է որպես ընտանեկան երեկո։",
