    body: [
      "Վահագն Ստամբոլցյանի անվան երգեհոնային երաժշտության չորրորդ միջազգային փառատոնի շրջանակում նոյեմբերի 7-ին Կոմիտասի անվան կամերային երաժշտության տանը համերգ է՝ նվիրված Մակար Եկմալյանի 170-ամյակին։ Բեմում ութ երգեհոնահար է՝ Աննա Բակունց, Հարություն Թագվորյան, Թերեզա Ոսկանյան, Արմեն Աղաջանյան, Լուսինե Հարությունյան, Աննա Առուստամյան, Հովհաննես Մանուկյան և Արփինե Հարությունյան, ինչպես նաև սոպրանո Ռիտա Պետրոսյանը։",
      "## Ծրագիրը",
      "Եկմալյանի պատարագից՝ «Հայր մեր», «Սուրբ-սուրբ», «Ի կույս վիմեն», «Ամեն Հայր Սուրբ», «Լցաք ի բարութեանց» (Ստամբոլցյանի մշակմամբ), Զատկի «Գովեա Երուսաղեմ» շարականը, «Խորհուրդ խորին», «Տեր ողորմեա» և «Յորժամ»՝ Առնո Բաբաջանյանի մշակմամբ։ Կողքին՝ հայ կոմպոզիտորների երգեհոնային երկեր. Գրիգոր Առաքելյանի չորս պրելյուդ «Մաշտոց» շարքից, Լուսինե Գրիգորյանի «Աղերսը» Կոմիտասի խոսքերով, Վաչե Շարաֆյանի «Հետփայլը», Գրիգոր Նարեկացու տաղերը Երվանդ Երկանյանի մշակմամբ, Միխայիլ Կոկժաևի «Պարզ մեղեդին», Տիգրան Համբարյանի պրելյուդը, Հովհաննես Մանուկյանի երկու խորալը, անանուն «Խնկի ծառին նման ես»-ը և Բաբաջանյանի «Վոկալիզը»՝ Արփինե Հարությունյանի երգեհոնային փոխադրումներով։",
      "## Երբ և որքան",
      "Նոյեմբերի 7-ին, շաբաթ, ժամը 19:00-ին, Իսահակյան 1 հասցեում։ Տոմսերը 3000-ից 5000 դրամ են՝ EventHub-ում։ Համերգը նախատեսված է 6 տարեկանից բարձր հանդիսատեսի համար։ Նույն փառատոնի շրջանակում հոկտեմբերի 24-ին <a href=\"/events/guy-bovet-organ-festival-komitas-chamber-music-house-2026/\" title=\"Գի Բովե՝ երգեհոնի փառատոն Երևանում, հոկտեմբերի 24\">Գի Բովեի մենահամերգն</a> է, իսկ նույն դահլիճում հոկտեմբերի 29-ին՝ <a href=\"/events/pergolesi-stabat-mater-komitas-chamber-music-house-2026/\" title=\"Պերգոլեզիի Stabat Mater-ը Երևանում՝ հոկտեմբերի 29\">Պերգոլեզիի Stabat Mater-ը</a>։",
    ],
